package com.trainflow.program; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/training-cases/{caseId}/program") public class ProgramController {private final ProgramService s;public ProgramController(ProgramService s){this.s=s;}@GetMapping ProgramResponse get(@PathVariable UUID caseId){return s.get(caseId);}@PostMapping@ResponseStatus(HttpStatus.CREATED)ProgramResponse create(@PathVariable UUID caseId,@Valid@RequestBody ProgramRequest r){return s.create(caseId,r);}@PatchMapping ProgramResponse update(@PathVariable UUID caseId,@Valid@RequestBody ProgramRequest r){return s.update(caseId,r);}@PostMapping("/submit")ProgramResponse submit(@PathVariable UUID caseId){return s.submit(caseId);}@PostMapping("/return")ProgramResponse back(@PathVariable UUID caseId,@Valid@RequestBody ReturnRequest r){return s.returnProgram(caseId,r.reason());}@PostMapping("/validate")ProgramResponse validate(@PathVariable UUID caseId){return s.validate(caseId);}@PostMapping("/days")ProgramResponse addDay(@PathVariable UUID caseId,@Valid@RequestBody DayRequest r){return s.addDay(caseId,r);}@PatchMapping("/days/{dayId}")ProgramResponse updateDay(@PathVariable UUID caseId,@PathVariable UUID dayId,@Valid@RequestBody DayRequest r){return s.updateDay(caseId,dayId,r);}@DeleteMapping("/days/{dayId}")ProgramResponse removeDay(@PathVariable UUID caseId,@PathVariable UUID dayId){return s.removeDay(caseId,dayId);}@PostMapping("/days/{dayId}/move-up")ProgramResponse dayUp(@PathVariable UUID caseId,@PathVariable UUID dayId){return s.moveDay(caseId,dayId,-1);}@PostMapping("/days/{dayId}/move-down")ProgramResponse dayDown(@PathVariable UUID caseId,@PathVariable UUID dayId){return s.moveDay(caseId,dayId,1);}@PostMapping("/days/{dayId}/items")ProgramResponse addItem(@PathVariable UUID caseId,@PathVariable UUID dayId,@Valid@RequestBody ItemRequest r){return s.addItem(caseId,dayId,r);}@PatchMapping("/items/{itemId}")ProgramResponse updateItem(@PathVariable UUID caseId,@PathVariable UUID itemId,@Valid@RequestBody ItemPatchRequest r){return s.updateItem(caseId,itemId,r);}@DeleteMapping("/items/{itemId}")ProgramResponse removeItem(@PathVariable UUID caseId,@PathVariable UUID itemId){return s.removeItem(caseId,itemId);}@PostMapping("/items/{itemId}/move-up")ProgramResponse itemUp(@PathVariable UUID caseId,@PathVariable UUID itemId){return s.moveItem(caseId,itemId,-1);}@PostMapping("/items/{itemId}/move-down")ProgramResponse itemDown(@PathVariable UUID caseId,@PathVariable UUID itemId){return s.moveItem(caseId,itemId,1);}@PostMapping("/generate-draft")ProgramResponse generate(@PathVariable UUID caseId){return s.generate(caseId);}}
